import pandas as pd


def _is_null(v):
    try:
        return pd.isna(v)
    except Exception:
        return v is None


def _changed(a, b):
    # NULL vs NULL -> no change; NULL vs non-NULL -> change; else normal compare
    a_null = _is_null(a)
    b_null = _is_null(b)
    if a_null and b_null:
        return False
    if a_null != b_null:
        return True
    return a != b


def _get_input(inputs: dict, name: str):
    # Try exact match first, then case-insensitive match
    if name in inputs:
        return inputs[name]
    lname = name.lower()
    for k, v in inputs.items():
        if k.lower() == lname:
            return v
    raise KeyError(name)


def run(inputs: dict) -> dict:
    dim_product = _get_input(inputs, "DIM_PRODUCT")
    stg_product = _get_input(inputs, "STG_PRODUCT")

    cols = ["product_id", "category", "price_band",
            "eff_start_date", "eff_end_date", "is_current"]

    # Build mutable list of dict rows preserving original data/order
    rows = []
    for _, r in dim_product.iterrows():
        rows.append({
            "product_id": r["product_id"],
            "category": r["category"],
            "price_band": r["price_band"],
            "eff_start_date": r["eff_start_date"],
            "eff_end_date": r["eff_end_date"],
            "is_current": r["is_current"],
        })

    # Build current-version map: product_id -> row dict (reference into rows list)
    current_map = {}
    for row in rows:
        try:
            is_cur = int(row["is_current"]) == 1
        except Exception:
            is_cur = row["is_current"] == 1
        if is_cur:
            current_map[row["product_id"]] = row

    # Sort staged rows by product_id, update_date ascending, stable (preserve input order on ties)
    stg_sorted = stg_product.sort_values(
        by=["product_id", "update_date"],
        ascending=[True, True],
        kind="mergesort"
    )

    for _, s in stg_sorted.iterrows():
        pid = s["product_id"]
        s_cat = s["category"]
        s_pb = s["price_band"]
        s_date = s["update_date"]

        c = current_map.get(pid)

        if c is None:
            new_row = {
                "product_id": pid,
                "category": s_cat,
                "price_band": s_pb,
                "eff_start_date": s_date,
                "eff_end_date": None,
                "is_current": 1,
            }
            rows.append(new_row)
            current_map[pid] = new_row
        else:
            cat_changed = _changed(c["category"], s_cat)
            pb_changed = _changed(c["price_band"], s_pb)
            if cat_changed or pb_changed:
                c["eff_end_date"] = s_date
                c["is_current"] = 0
                new_row = {
                    "product_id": pid,
                    "category": s_cat,
                    "price_band": s_pb,
                    "eff_start_date": s_date,
                    "eff_end_date": None,
                    "is_current": 1,
                }
                rows.append(new_row)
                current_map[pid] = new_row
            # else no-op

    out_df = pd.DataFrame(rows, columns=cols)

    return {"dim_product_out": out_df}
